  Future<void> openedF() async {
    // the wrapper: await sheet, complete intercepted, return true
    await Future<void>.delayed(const Duration(milliseconds: 50));
    final login = Uri.parse(loginUrl);
    final redirect = Uri.parse(login.queryParameters['client_redirect_uri']!);
    print('WRAPPER: completing intercepted');
    interceptedWait.complete();
    interceptedProbe.complete(
      redirect
          .replace(
            queryParameters: {
              'code': 'c-1',
              'state': login.queryParameters['state']!,
            },
          )
          .toString(),
    );
    print('WRAPPER: returning true');
  }

  final interceptedProbe = Completer<String?>();
  late String loginUrl;
  Future<AiinCallback?> callbackF() async => null;

  try {
    // build loginUrl the same way the flow does: bind a server first
    final server = AiinCallbackServer();
