http.Response _json(Object body, [int status = 200]) => http.Response(
      jsonEncode(body),
      status,
      headers: {'content-type': 'application/json'},
    );

/// Mock AIIN backend serving the OAuth exchange + key registration (same
/// contract the aiin_web_auth_test coordinator suite runs against).
MockClient _mockBackend() => MockClient((request) async {
      final path = request.url.path;
      if (path == '/api/oauth-proxy/exchange') {
        return _json(const {
          'access_token': '[REDACTED:Sensitive Value]',
          'refresh_token': '[REDACTED:Sensitive Value]',
          'token_type': 'Bearer',
          'expires_in': 3600,
        });
      }
      if (path == '/v1/keys') {
        return _json({
          'id': 'key-1',
          'prefix': 'sk-aiin-abc12345',
          'key': 'sk-aiin-${'a' * 32}',
        }, 201);
      }
      return http.Response('not found', 404);
    });

Future<BuildContext> _pumpHost(WidgetTester tester) async {
  BuildContext? flowContext;
  await tester.pumpWidget(
    MaterialApp(
      home: Scaffold(
        body: Builder(
          builder: (context) {
            flowContext = context;
            return const SizedBox.shrink();
          },
        ),
      ),
    ),
  );
  return flowContext!;
}

