        !surfaceClosed.isCompleted &&
        !interceptedCallback.isCompleted) {
      print('RACE: surfaceClosed via opened settle');
      surfaceClosed.completeError(const AiinSurfaceClosedException());
    }
  }, onError: (Object e, StackTrace s) {
    print('RACE: opened error $e');
    if (!openError.isCompleted) openError.completeError(e, s);
  });
  openError.future.ignore();
  surfaceClosed.future.ignore();
  final result = Future.any([
    callbackFuture.then((c) => (c, 0)),
    openError.future,
    surfaceClosed.future,
    interceptedCallback.future,
  ]);
  print('RACE: listeners attached, race armed');
  return result;
}

