  final surfaceClosed = Completer<Never>();
  final interceptedCallback = Completer<(AiinCallback?, int)>();
  if (interceptedF != null) {
    print('RACE: attaching intercepted listener');
    interceptedF.then((url) {
      print('RACE: intercepted.then fired url=$url');
      if (url != null) {
        if (!interceptedCallback.isCompleted) {
          interceptedCallback.complete((AiinCallback.fromRedirectUrl(url), 1));
        }
        return;
      }
      if (!surfaceClosed.isCompleted && !interceptedCallback.isCompleted) {
        print('RACE: surfaceClosed via intercepted null');
        surfaceClosed.completeError(const AiinSurfaceClosedException());
      }
    }, onError: (Object e, StackTrace s) {
      print('RACE: intercepted error $e');
      if (!openError.isCompleted) openError.completeError(e, s);
    });
