      if (!surfaceClosed.isCompleted && !interceptedCallback.isCompleted) {
        print('RACE: surfaceClosed via intercepted null');
        surfaceClosed.completeError(const AiinSurfaceClosedException());
      }
    }, onError: (Object e, StackTrace s) {
      print('RACE: intercepted error $e');
      if (!openError.isCompleted) openError.completeError(e, s);
