Future<void> v2() async {
  final c = Completer<String>();
  c.future.then((_) => print('V2-L1: c'));
  final opened = body(c);
  opened.then((_) => print('V2-L2: opened'));
  await opened;
  print('V2: done');
}

Future<void> body(Completer<String> c) async {
  await Future<void>.value(); // one microtask hop, no timer
  c.complete('x');
  print('V2: body completed c, returning');
}

Future<void> main() async {
  v1();
  await Future<void>.delayed(const Duration(milliseconds: 10));
  print('--- v2 ---');
  await v2();
}
